import * as THREE from './vendor/three.module.js';
import {hash,triangleCount,GeometryBuilder,roofGeometry,roadClass} from './lowpoly.js';
export const DRESSING_LIMITS={trees:800,stops:140,signals:48,landmarks:3};
export function distanceToSegment(p,a,b){const dx=b.x-a.x,dz=b.z-a.z,d=dx*dx+dz*dz,t=d?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.z-a.z)*dz)/d)):0;return Math.hypot(p.x-a.x-t*dx,p.z-a.z-t*dz);}
class Grid{
 constructor(size=64){this.size=size;this.cells=new Map();}
 keys(x0,z0,x1,z1){const out=[];for(let x=Math.floor(x0/this.size);x<=Math.floor(x1/this.size);x++)for(let z=Math.floor(z0/this.size);z<=Math.floor(z1/this.size);z++)out.push(x+':'+z);return out;}
 add(item,x0,z0,x1,z1){for(const k of this.keys(x0,z0,x1,z1)){if(!this.cells.has(k))this.cells.set(k,[]);this.cells.get(k).push(item);}}
 query(p,r){return [...new Set(this.keys(p.x-r,p.z-r,p.x+r,p.z+r).flatMap(k=>this.cells.get(k)||[]))];}
}
export function planDressing(town,{demo=false}={}){
 const seed=String(town.seed||town.id),bounds=town.bounds,roadGrid=new Grid(),obstacles=new Grid(),segments=[],junctions=new Map(),landmarks=[],trees=[],stops=[],signals=[];
 const reserve=p=>obstacles.add(p,p.x-p.radius,p.z-p.radius,p.x+p.radius,p.z+p.radius);
 for(const h of town.premises)reserve({x:h.x,z:h.z,radius:Math.hypot(h.width+9,h.depth+7)/2,premiseId:h.id});
 for(const n of Object.values(town.networks||{}).flatMap(n=>n.nodes||[]))if(['substation','pump_station','city_gate_regulator'].includes(n.kind))reserve({x:n.x,z:n.z,radius:23});
 for(const road of town.roads){for(let i=1;i<road.points.length;i++){const a=road.points[i-1],b=road.points[i];if(Math.hypot(b.x-a.x,b.z-a.z)<.1)continue;const seg={a,b,road};segments.push(seg);roadGrid.add(seg,Math.min(a.x,b.x),Math.min(a.z,b.z),Math.max(a.x,b.x),Math.max(a.z,b.z));}
  for(const reverse of [false,true]){const ps=reverse?[...road.points].reverse():road.points,p=ps[0],q=ps[1];if(!q)continue;const key=p.x.toFixed(1)+':'+p.z.toFixed(1);if(!junctions.has(key))junctions.set(key,{x:p.x,z:p.z,arms:[]});const len=Math.hypot(q.x-p.x,q.z-p.z);if(len>.1)junctions.get(key).arms.push({dx:(q.x-p.x)/len,dz:(q.z-p.z)/len,road});}}
 const inside=(p,r)=>p.x-r>bounds.minX+3&&p.x+r<bounds.maxX-3&&p.z-r>bounds.minZ+3&&p.z+r<bounds.maxZ-3;
 const clear=(p,r,roadMargin=8)=>inside(p,r)&&obstacles.query(p,r).every(o=>Math.hypot(o.x-p.x,o.z-p.z)>=o.radius+r)&&roadGrid.query(p,r+roadMargin).every(s=>distanceToSegment(p,s.a,s.b)>=r+roadMargin);
 const cx=(bounds.minX+bounds.maxX)/2,cz=(bounds.minZ+bounds.maxZ)/2;
 if(demo){const candidates=[];for(const s of segments){const dx=s.b.x-s.a.x,dz=s.b.z-s.a.z,len=Math.hypot(dx,dz);if(len<30)continue;for(const t of [.3,.7])for(const side of [-1,1])candidates.push({x:s.a.x+dx*t,z:s.a.z+dz*t,nx:-dz/len*side,nz:dx/len*side,angle:Math.atan2(dz,dx)+(side===1?Math.PI:0),key:s.road.id+':'+t+':'+side});}candidates.sort((a,b)=>Math.hypot(a.x-cx,a.z-cz)-Math.hypot(b.x-cx,b.z-cz)||(hash(seed+a.key)-hash(seed+b.key)));
  for(const spec of [{kind:'school',label:'Maplewood school',width:48,depth:42,height:7},{kind:'apartments',label:'Cedar Court apartments',width:36,depth:30,height:14},{kind:'church',label:'Town church',width:25,depth:32,height:18}]){const radius=Math.hypot(spec.width,spec.depth)/2+2;let found=null;for(const c of candidates){for(const extra of [12,28,50]){const p={x:c.x+c.nx*(radius+extra),z:c.z+c.nz*(radius+extra)};if(clear(p,radius)){found={...spec,...p,radius,angle:c.angle,id:'VISUAL-'+spec.kind,visualOnly:true};break;}}if(found)break;}if(found){landmarks.push(found);reserve(found);}}
 }
 // Explicit engine landmarks can be rendered, but the viewer never invents their customer entities.
 if(!demo){for(const f of town.facilities||[]){const kind=String(f.kind||'');if(!['school','church','apartments','apartment'].includes(kind)||!Number.isFinite(f.x)||!Number.isFinite(f.z))continue;const h=town.premises.find(h=>h.id===f.premiseId);if(h)continue;const width=f.widthM||30,depth=f.depthM||30,p={id:f.id,label:f.label||kind,kind:kind==='apartment'?'apartments':kind,x:f.x,z:f.z,width,depth,height:f.heightM||10,angle:f.angle||0,radius:Math.hypot(width,depth)/2,visualOnly:false};landmarks.push(p);reserve(p);}}
 const ordered=[...junctions.values()].filter(j=>j.arms.length>=3).sort((a,b)=>hash(seed+':junction:'+a.x+','+a.z)-hash(seed+':junction:'+b.x+','+b.z));
 for(const j of ordered){const major=j.arms.some(a=>['primary','secondary','tertiary'].includes(roadClass(a.road))),signal=major&&signals.length<DRESSING_LIMITS.signals&&j.arms.length>=3;for(const arm of [...j.arms].sort((a,b)=>String(a.road.id).localeCompare(String(b.road.id))).slice(0,signal?2:1)){const setback=['primary','secondary'].includes(roadClass(arm.road))?12:['tertiary'].includes(roadClass(arm.road))?10:8.5,p={x:j.x+arm.dx*12-arm.dz*setback,z:j.z+arm.dz*12+arm.dx*setback,angle:Math.atan2(arm.dx,arm.dz),junction:{x:j.x,z:j.z},radius:1.3};if(!inside(p,2)||!obstacles.query(p,1.3).every(o=>Math.hypot(o.x-p.x,o.z-p.z)>o.radius+1.3)||roadGrid.query(p,8).some(s=>distanceToSegment(p,s.a,s.b)<(['primary','secondary'].includes(roadClass(s.road))?10:['tertiary'].includes(roadClass(s.road))?7.5:6.3)))continue;if(signal&&signals.length<DRESSING_LIMITS.signals)signals.push(p);else if(!signal&&stops.length<DRESSING_LIMITS.stops)stops.push(p);}}
 const target=Math.min(DRESSING_LIMITS.trees,Math.round(town.premises.length*.24)+60),homeOrder=[...town.premises].sort((a,b)=>hash(seed+':tree:'+a.id)-hash(seed+':tree:'+b.id));
 for(const h of homeOrder){if(trees.length>=target)break;const random=hash(seed+':tree-shape:'+h.id),nx=Math.sin(h.angle)*h.side,nz=-Math.cos(h.angle)*h.side,offset=25+(random%160)/10,side=random%2?1:-1,p={x:h.x-nx*offset+Math.cos(h.angle)*side*7,z:h.z-nz*offset+Math.sin(h.angle)*side*7,radius:3.2,kind:random%3,scale:.8+(random%40)/100,angle:(random%628)/100};if(clear(p,3.2,8.5)){trees.push(p);reserve(p);}}
 return {schemaVersion:'viewer-dressing/1.0',visualOnly:true,trees,stops,signals,landmarks,limits:DRESSING_LIMITS};
}
function treeGeometry(kind){const b=new GeometryBuilder();b.box('#8b795d',0,1.25,0,.48,2.5,.48);const g=kind===2?new THREE.ConeGeometry(2,4.8,4):kind===1?new THREE.IcosahedronGeometry(2.3,0):new THREE.OctahedronGeometry(2.4,0);b.add(g,['#74a257','#91b56a','#578b61'][kind],0,kind===2?4:3.6,0,1,kind===1?1.05:1,1);g.dispose();return b.build();}
function stopGeometry(){const b=new GeometryBuilder();b.box('#a3a89f',0,1.5,0,.09,3,.09);const g=new THREE.CircleGeometry(.52,8);b.add(g,'#f6f3e9',0,2.6,.055);b.add(g,'#bd554b',0,2.6,.063,.86,.86,1);g.dispose();return b.build();}
function signalGeometry(){const b=new GeometryBuilder();b.box('#858f82',0,2.1,0,.16,4.2,.16).box('#858f82',.75,4.1,0,1.5,.14,.14).box('#dfb653',1.4,3.7,0,.44,1.16,.35);const g=new THREE.CircleGeometry(.13,6);for(let i=0;i<3;i++)b.add(g,['#d5634a','#745e38','#7ba873'][i],1.4,4.02-i*.30,.182);g.dispose();return b.build();}
function landmarkGeometry(kind){const b=new GeometryBuilder(),wall='#e5dfcb',roof='#89938b',glass='#789698',trim='#f7f1df';
 b.box('#c3c7af',0,.006,0,1,.012,1);
 if(kind==='apartments'){for(const x of [-.24,.24]){b.box(wall,x,.39,0,.40,.78,.59).box(roof,x,.795,0,.43,.05,.62);for(let floor=0;floor<4;floor++)for(const dx of [-.10,.10]){b.plane(glass,x+dx,.12+floor*.18,-.298,.08,.105,0,Math.PI);b.plane(glass,x+dx,.12+floor*.18,.298,.08,.105);}}b.box('#d4c3ac',0,.225,0,.14,.45,.4).box(trim,0,.20,-.32,.10,.025,.13);b.plane(glass,0,.10,-.211,.07,.16,0,Math.PI);for(let x=-.40;x<=.40;x+=.1)b.plane('#f4f0dd',x,.014,-.41,.005,.10,-Math.PI/2);}
 else if(kind==='school'){b.box(wall,0,.25,.22,.82,.50,.29).box(wall,-.31,.185,-.07,.20,.37,.34).box(wall,.31,.185,-.07,.20,.37,.34);b.box(roof,0,.515,.22,.85,.035,.32).box(roof,-.31,.385,-.07,.23,.035,.36).box(roof,.31,.385,-.07,.23,.035,.36);for(let x=-.35;x<.4;x+=.1)b.plane(glass,x,.36,.072,.065,.17,0,Math.PI);b.box('#bbc4b3',0,.01,-.28,.37,.008,.3);for(const z of [-.405,-.16])b.plane(trim,0,.015,z,.31,.006,-Math.PI/2);for(const x of [-.155,.155])b.plane(trim,x,.015,-.283,.006,.25,-Math.PI/2);b.plane(trim,0,.016,-.283,.31,.006,-Math.PI/2);b.box('#9eaa95',-.42,.30,-.34,.008,.6,.008).plane('#d9af61',-.36,.57,-.34,.12,.07);}
 else{b.box(wall,0,.24,.08,.50,.48,.66);const g=roofGeometry();b.add(g,roof,0,.48,.08,.57,.20,.70);g.dispose();b.box('#e8dec5',0,.40,-.26,.24,.80,.25);const cone=new THREE.ConeGeometry(1,1,4);b.add(cone,roof,0,.89,-.26,.20,.18,.20,0,Math.PI/4);cone.dispose();b.box(trim,0,1.035,-.26,.014,.13,.014).box(trim,0,1.06,-.26,.072,.012,.014);b.plane('#8b8773',0,.17,-.389,.12,.23,0,Math.PI);const round=new THREE.CircleGeometry(.06,8);b.add(round,glass,0,.56,-.388);round.dispose();for(const x of [-.252,.252])for(const z of [-.08,.12,.30])b.plane(glass,x,.32,z,.075,.22,0,Math.sign(x)*Math.PI/2);}
 return b.build();
}
export class TownDressing{
 constructor(root,town,heightAt,options){this.plan=planDressing(town,options);this.group=new THREE.Group();root.add(this.group);this.meshes=[];const material=new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:true,side:THREE.DoubleSide});const add=(geometry,items,transform)=>{const m=new THREE.InstancedMesh(geometry,material,items.length),d=new THREE.Object3D();items.forEach((p,i)=>{d.position.set(p.x,heightAt(p.x,p.z),p.z);d.rotation.set(0,p.angle||0,0);d.scale.setScalar(p.scale||1);transform?.(d,p);d.updateMatrix();m.setMatrixAt(i,d.matrix);});m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();m.castShadow=false;m.receiveShadow=true;this.group.add(m);this.meshes.push(m);return m;};
  for(let kind=0;kind<3;kind++)add(treeGeometry(kind),this.plan.trees.filter(p=>p.kind===kind));add(stopGeometry(),this.plan.stops);add(signalGeometry(),this.plan.signals);
  for(const kind of ['school','apartments','church'])add(landmarkGeometry(kind),this.plan.landmarks.filter(p=>p.kind===kind),(d,p)=>{d.scale.set(p.width,p.height,p.depth);});
  // One shared text atlas for all STOP labels, independent of the number of signs.
  if(typeof document!=='undefined'&&this.plan.stops.length){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const ctx=canvas.getContext('2d');if(ctx){ctx.fillStyle='#fff7e9';ctx.font='bold 42px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('STOP',64,32);const texture=new THREE.CanvasTexture(canvas),g=new THREE.PlaneGeometry(.73,.37),m=new THREE.InstancedMesh(g,new THREE.MeshBasicMaterial({map:texture,transparent:true,side:THREE.DoubleSide,depthWrite:false}),this.plan.stops.length),d=new THREE.Object3D();this.plan.stops.forEach((p,i)=>{d.position.set(p.x+Math.sin(p.angle)*.075,heightAt(p.x,p.z)+2.6,p.z+Math.cos(p.angle)*.075);d.rotation.set(0,p.angle,0);d.updateMatrix();m.setMatrixAt(i,d.matrix);});m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();this.group.add(m);this.meshes.push(m);this.texture=texture;}}
 }
 setVisible(v){this.group.visible=v;}
 stats(){return {dressingTriangles:this.meshes.reduce((s,m)=>s+triangleCount(m.geometry)*m.count,0),dressingBatches:this.meshes.filter(m=>m.count>0).length,trees:this.plan.trees.length,stopSigns:this.plan.stops.length,trafficLights:this.plan.signals.length,landmarks:this.plan.landmarks.length};}
}
